/* ==========================================================================
   RentRide Home Stylesheet (rentride-home.css)
   Light Neutral Surface System + Royal/Navy Accents + Deep Navy-Slate Footer
   ========================================================================== */

:root {
  --bg-page: #f4f6f9;
  --bg-surface: #ffffff;
  --bg-card-soft: #eef2f6;
  --bg-card-hover: #e7edf4;
  --border-subtle: #dce3ec;
  --border-strong: #c2cddb;

  --text-primary: #0f2742;
  --text-secondary: #425469;
  --text-muted: #5d7086;

  --navy-deep: #0f2742;
  --navy-royal: #173f6e;
  --navy-accent: #1d4ed8;
  --teal-brand: #0ea57a;
  --teal-bright: #2dd4bf;
  --teal-soft: #e6f7f2;

  --error-color: #b91c1c;
  --error-bg: #fef2f2;
  --success-color: #047857;
  --success-bg: #ecfdf5;

  --shadow-card: 0 10px 28px rgba(15, 39, 66, 0.06);
  --shadow-hover: 0 14px 32px rgba(15, 39, 66, 0.1);
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-pill: 999px;
  --transition-fast: 180ms ease;
}

/* Reset & Base */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-page);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img,
svg {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
select {
  font: inherit;
}

/* Visible Keyboard Focus Outlines */
:focus-visible {
  outline: 3px solid var(--navy-accent);
  outline-offset: 2px;
}

.site-footer :focus-visible {
  outline-color: var(--teal-bright);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Skip Link */
.skip-link {
  position: absolute;
  left: 1rem;
  top: -3rem;
  z-index: 1000;
  background: var(--navy-deep);
  color: #ffffff;
  padding: 0.65rem 1rem;
  border-radius: 8px;
  font-weight: 600;
  transition: top var(--transition-fast);
}

.skip-link:focus {
  top: 1rem;
}

/* Layout Container */
.container {
  width: min(1160px, 100% - 2rem);
  margin-inline: auto;
}

/* ==========================================================================
   Header & Navigation
   ========================================================================== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: rgba(255, 255, 255, 0.94);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border-subtle);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 72px;
  gap: 1.25rem;
}

.brand-logo {
  font-size: 1.55rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  display: inline-flex;
  align-items: center;
}

.brand-rent {
  color: var(--navy-deep);
}

.brand-ride {
  color: var(--teal-brand);
}

.nav-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 44px;
  height: 44px;
  padding: 0 10px;
  background: var(--bg-card-soft);
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  cursor: pointer;
}

.nav-toggle-bar {
  display: block;
  width: 100%;
  height: 2.5px;
  background: var(--navy-deep);
  border-radius: 2px;
}

.nav-list {
  display: flex;
  align-items: center;
  list-style: none;
  margin: 0;
  padding: 0;
  gap: 0.35rem;
}

.nav-link {
  display: inline-flex;
  align-items: center;
  padding: 0.5rem 0.8rem;
  border-radius: 8px;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-secondary);
  transition: background-color var(--transition-fast), color var(--transition-fast);
}

.nav-link:hover {
  background-color: var(--bg-card-soft);
  color: var(--navy-deep);
}

.nav-link-account {
  background-color: var(--navy-deep);
  color: #ffffff;
  margin-left: 0.35rem;
}

.nav-link-account:hover {
  background-color: var(--navy-royal);
  color: #ffffff;
}

/* ==========================================================================
   Buttons
   ========================================================================== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  padding: 0.72rem 1.25rem;
  border-radius: 10px;
  font-weight: 600;
  font-size: 0.96rem;
  border: 1.5px solid transparent;
  cursor: pointer;
  transition: background-color var(--transition-fast), color var(--transition-fast), border-color var(--transition-fast), transform var(--transition-fast);
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background-color: var(--navy-royal);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--navy-deep);
}

.btn-secondary {
  background-color: var(--bg-surface);
  color: var(--navy-deep);
  border-color: var(--border-strong);
}

.btn-secondary:hover {
  background-color: var(--bg-card-soft);
}

.btn-outline {
  background-color: transparent;
  color: var(--navy-royal);
  border-color: var(--navy-royal);
}

.btn-outline:hover {
  background-color: var(--navy-royal);
  color: #ffffff;
}

.btn-ghost {
  background-color: var(--bg-card-soft);
  color: var(--text-secondary);
  border-color: var(--border-subtle);
}

.btn-ghost:hover {
  background-color: var(--bg-card-hover);
  color: var(--navy-deep);
}

.btn-block {
  flex: 1;
}

/* ==========================================================================
   Hero Section & Search Card
   ========================================================================== */
.hero-section {
  padding: 3.25rem 0 3.5rem;
  background: radial-gradient(circle at top right, rgba(23, 63, 110, 0.08), transparent 48%), var(--bg-page);
}

.hero-grid {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 2.5rem;
  align-items: center;
}

.hero-eyebrow {
  display: inline-block;
  padding: 0.35rem 0.85rem;
  border-radius: var(--radius-pill);
  background-color: var(--teal-soft);
  color: #0b7a5b;
  font-size: 0.84rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  margin-bottom: 1rem;
}

.hero-title {
  margin: 0 0 1rem;
  font-size: clamp(2rem, 4vw, 3rem);
  line-height: 1.15;
  letter-spacing: -0.025em;
  color: var(--navy-deep);
}

.brand-inline {
  white-space: nowrap;
}

.hero-subtitle {
  margin: 0 0 1.6rem;
  font-size: 1.08rem;
  color: var(--text-secondary);
  max-width: 54ch;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.85rem;
  margin-bottom: 1.5rem;
}

.hero-highlights {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem 1.4rem;
  list-style: none;
  margin: 0;
  padding: 0;
  font-size: 0.9rem;
  color: var(--text-muted);
  font-weight: 500;
}

.hero-highlights li::before {
  content: "✓";
  color: var(--teal-brand);
  font-weight: 800;
  margin-right: 0.4rem;
}

/* Search Card */
.search-card {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 1.65rem;
  box-shadow: var(--shadow-card);
}

.search-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 1.1rem;
}

.search-card-title {
  margin: 0;
  font-size: 1.3rem;
  color: var(--navy-deep);
}

.saved-badge {
  font-size: 0.76rem;
  font-weight: 700;
  padding: 0.25rem 0.6rem;
  border-radius: var(--radius-pill);
  background-color: var(--teal-soft);
  color: #0b7a5b;
}

.search-form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.85rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.form-label {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--navy-deep);
}

.form-label-sm {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.form-control {
  width: 100%;
  padding: 0.68rem 0.85rem;
  border: 1.5px solid var(--border-strong);
  border-radius: 10px;
  background-color: #ffffff;
  color: var(--text-primary);
  font-size: 0.95rem;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.form-control-sm {
  padding: 0.5rem 0.65rem;
  font-size: 0.9rem;
}

.form-control:hover {
  border-color: var(--navy-royal);
}

.form-control[aria-invalid="true"] {
  border-color: var(--error-color);
  background-color: var(--error-bg);
}

.field-error {
  margin: 0;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--error-color);
}

.search-form-actions {
  display: flex;
  gap: 0.65rem;
  margin-top: 0.25rem;
}

.search-status {
  padding: 0.75rem 0.9rem;
  border-radius: 10px;
  font-size: 0.9rem;
  font-weight: 600;
}

.search-status.is-success {
  background-color: var(--success-bg);
  color: var(--success-color);
  border: 1px solid #a7f3d0;
}

.search-status.is-error {
  background-color: var(--error-bg);
  color: var(--error-color);
  border: 1px solid #fecaca;
}

/* ==========================================================================
   Sections & Fleet Cards
   ========================================================================== */
.section-block {
  padding: 3.5rem 0;
}

.section-alt {
  background-color: rgba(255, 255, 255, 0.55);
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}

.section-header-row {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1.25rem;
  margin-bottom: 1.4rem;
}

.section-heading-center {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 2.25rem;
}

.section-eyebrow {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--teal-brand);
  margin-bottom: 0.35rem;
}

.section-title {
  margin: 0 0 0.45rem;
  font-size: clamp(1.55rem, 2.5vw, 2rem);
  color: var(--navy-deep);
}

.section-subtitle {
  margin: 0;
  color: var(--text-secondary);
}

.filter-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.filter-pill {
  padding: 0.48rem 0.95rem;
  border-radius: var(--radius-pill);
  border: 1px solid var(--border-strong);
  background-color: var(--bg-surface);
  color: var(--text-secondary);
  font-size: 0.88rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color var(--transition-fast), color var(--transition-fast), border-color var(--transition-fast);
}

.filter-pill:hover {
  background-color: var(--bg-card-soft);
  color: var(--navy-deep);
}

.filter-pill.is-active {
  background-color: var(--navy-deep);
  border-color: var(--navy-deep);
  color: #ffffff;
}

.fleet-status {
  margin: 0 0 1.2rem;
  font-size: 0.92rem;
  color: var(--text-muted);
  font-weight: 500;
}

.vehicle-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1.25rem;
}

.vehicle-card {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast), border-color var(--transition-fast);
}

.vehicle-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-hover);
  border-color: var(--border-strong);
}

.vehicle-card.is-selected {
  border-color: var(--teal-brand);
  box-shadow: 0 0 0 2px rgba(14, 165, 122, 0.25), var(--shadow-card);
}

.vehicle-card[hidden] {
  display: none;
}

.vehicle-visual {
  position: relative;
  background-color: var(--bg-card-soft);
  padding: 1.65rem 1rem 1.15rem;
  border-bottom: 1px solid var(--border-subtle);
}

.car-svg {
  width: 100%;
  height: 82px;
}

.vehicle-badge {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  padding: 0.22rem 0.65rem;
  border-radius: var(--radius-pill);
  background-color: var(--navy-deep);
  color: #ffffff;
  font-size: 0.74rem;
  font-weight: 700;
}

.badge-teal {
  background-color: var(--teal-brand);
}

.vehicle-body {
  padding: 1.15rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  flex: 1;
}

.vehicle-title-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}

.vehicle-name {
  margin: 0;
  font-size: 1.05rem;
  color: var(--navy-deep);
}

.vehicle-price {
  font-size: 0.88rem;
  color: var(--text-secondary);
  white-space: nowrap;
}

.vehicle-price strong {
  font-size: 1.12rem;
  color: var(--navy-royal);
}

.vehicle-meta,
.vehicle-hubs {
  margin: 0;
  font-size: 0.85rem;
  color: var(--text-muted);
}

.btn-select-car {
  margin-top: auto;
  width: 100%;
  padding: 0.58rem 0.9rem;
}

.selected-vehicle-banner {
  margin: 1.35rem 0 0;
  padding: 0.9rem 1.1rem;
  border-radius: var(--radius-md);
  background-color: var(--teal-soft);
  border: 1px solid #99f6e4;
  color: var(--navy-deep);
  font-weight: 600;
}

/* ==========================================================================
   Travel Tools Grid & Promo/Account Banners
   ========================================================================== */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.35rem;
}

.tool-card {
  background-color: var(--bg-card-soft);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 1.6rem;
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.tool-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background-color: var(--navy-deep);
  color: #ffffff;
  font-weight: 800;
  font-size: 0.9rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.tool-title {
  margin: 0;
  font-size: 1.2rem;
  color: var(--navy-deep);
}

.tool-desc {
  margin: 0;
  font-size: 0.94rem;
  color: var(--text-secondary);
}

.tool-list {
  margin: 0;
  padding-left: 1.15rem;
  color: var(--text-muted);
  font-size: 0.88rem;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.tool-link {
  margin-top: auto;
  font-weight: 700;
  font-size: 0.92rem;
  color: var(--navy-royal);
}

.tool-link:hover {
  color: var(--teal-brand);
  text-decoration: underline;
}

.hub-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.hub-chip {
  padding: 0.38rem 0.75rem;
  border-radius: var(--radius-pill);
  border: 1px solid var(--border-strong);
  background-color: var(--bg-surface);
  color: var(--navy-deep);
  font-size: 0.83rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color var(--transition-fast), color var(--transition-fast);
}

.hub-chip:hover,
.hub-chip.is-active {
  background-color: var(--navy-royal);
  border-color: var(--navy-royal);
  color: #ffffff;
}

.mini-estimator {
  margin-top: auto;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.estimator-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.65rem;
}

.estimator-result {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  padding: 0.65rem 0.8rem;
  font-size: 0.88rem;
  color: var(--navy-deep);
}

.promo-account-grid {
  margin-top: 1.5rem;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.35rem;
}

.info-banner {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 1.4rem 1.5rem;
  box-shadow: var(--shadow-card);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.25rem;
}

.pill-tag {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.22rem 0.65rem;
  border-radius: var(--radius-pill);
  background-color: var(--teal-soft);
  color: #0b7a5b;
  margin-bottom: 0.45rem;
}

.pill-tag-navy {
  background-color: var(--bg-card-soft);
  color: var(--navy-royal);
}

.info-banner-title {
  margin: 0 0 0.3rem;
  font-size: 1.1rem;
  color: var(--navy-deep);
}

.info-banner-text {
  margin: 0;
  font-size: 0.9rem;
  color: var(--text-secondary);
}

/* ==========================================================================
   Rounded 3-Column Step / Benefit Strip Above Footer
   ========================================================================== */
.benefit-strip-section {
  padding: 2.75rem 0 3.25rem;
}

.benefit-strip-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.35rem;
}

.benefit-card {
  background-color: var(--bg-card-soft);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 1.55rem 1.6rem;
  box-shadow: var(--shadow-card);
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}

.benefit-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-hover);
}

.benefit-step {
  display: inline-block;
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--teal-brand);
  margin-bottom: 0.45rem;
}

.benefit-title {
  margin: 0 0 0.45rem;
  font-size: 1.15rem;
  color: var(--navy-deep);
}

.benefit-text {
  margin: 0;
  font-size: 0.93rem;
  color: var(--text-secondary);
}

/* ==========================================================================
   Deep Navy-Slate Footer
   ========================================================================== */
.site-footer {
  background-color: #0f2742;
  color: #dbe6f2;
  padding-top: 3.5rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.15fr 1.85fr;
  gap: 2.75rem;
  padding-bottom: 2.75rem;
}

.footer-wordmark {
  display: inline-flex;
  align-items: center;
  font-size: 1.65rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 0.85rem;
}

.brand-rent-light {
  color: #ffffff;
}

.brand-ride-footer {
  color: var(--teal-bright);
}

.footer-headline {
  margin: 0 0 0.7rem;
  font-size: 1.45rem;
  font-weight: 700;
  color: #ffffff;
  line-height: 1.25;
}

.footer-subtext {
  margin: 0;
  color: #b7c8db;
  font-size: 0.95rem;
  max-width: 40ch;
}

.footer-nav-columns {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.5rem;
}

.footer-col-heading {
  margin: 0 0 0.95rem;
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.09em;
  color: #ffffff;
}

.footer-links {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.footer-links a {
  display: inline-block;
  font-size: 0.94rem;
  color: #b7c8db;
  transition: color var(--transition-fast), transform var(--transition-fast);
}

.footer-links a:hover {
  color: var(--teal-bright);
  transform: translateX(3px);
}

.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  padding: 1.2rem 0;
}

.footer-bottom-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  font-size: 0.86rem;
  color: #9cb2ca;
}

.footer-bottom-inner p {
  margin: 0;
}

.footer-inline-link {
  color: #ffffff;
  text-decoration: underline;
  text-underline-offset: 3px;
}

