/* ==========================================================================
   RentRide Home Interactive Script (rentride-home.js)
   Handles responsive menu, form validation, fleet filtering, fare estimator,
   hub quick-select, and localStorage state persistence.
   ========================================================================== */

(() => {
  "use strict";

  const STORAGE_KEY = "rentride_home_state_v1";

  const state = {
    pickupCity: "",
    pickupDate: "",
    returnDate: "",
    vehicleType: "all",
    selectedCarName: "",
    selectedCarRate: 54,
    estDays: 3,
    estDistance: 240
  };

  // DOM References
  const navToggle = document.getElementById("navToggle");
  const primaryNav = document.getElementById("primaryNav");

  const searchForm = document.getElementById("rentalSearchForm");
  const pickupCityInput = document.getElementById("pickupCity");
  const pickupDateInput = document.getElementById("pickupDate");
  const returnDateInput = document.getElementById("returnDate");
  const vehicleTypeSelect = document.getElementById("vehicleType");
  const resetSearchBtn = document.getElementById("resetSearchBtn");
  const searchSummary = document.getElementById("searchSummary");
  const savedStateBadge = document.getElementById("savedStateBadge");

  const pickupCityError = document.getElementById("pickupCityError");
  const pickupDateError = document.getElementById("pickupDateError");
  const returnDateError = document.getElementById("returnDateError");

  const filterButtons = Array.from(document.querySelectorAll(".filter-pill"));
  const vehicleCards = Array.from(document.querySelectorAll(".vehicle-card"));
  const fleetFilterStatus = document.getElementById("fleetFilterStatus");
  const selectedVehicleNotice = document.getElementById("selectedVehicleNotice");
  const selectCarButtons = Array.from(document.querySelectorAll(".btn-select-car"));

  const hubButtons = Array.from(document.querySelectorAll(".hub-chip"));
  const prefillCityLinks = Array.from(document.querySelectorAll("[data-prefill-city]"));
  const estDaysInput = document.getElementById("estDays");
  const estDistanceInput = document.getElementById("estDistance");
  const estimatorResult = document.getElementById("estimatorResult");
  const accountStatusText = document.getElementById("accountStatusText");

  function getTodayISO() {
    const now = new Date();
    const offsetMs = now.getTimezoneOffset() * 60000;
    return new Date(now.getTime() - offsetMs).toISOString().split("T")[0];
  }

  function saveState() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch {
      // Ignore storage quota or private browsing errors gracefully.
    }
  }

  function loadState() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return false;
      const parsed = JSON.parse(raw);
      if (!parsed || typeof parsed !== "object") return false;

      if (typeof parsed.pickupCity === "string") state.pickupCity = parsed.pickupCity;
      if (typeof parsed.pickupDate === "string") state.pickupDate = parsed.pickupDate;
      if (typeof parsed.returnDate === "string") state.returnDate = parsed.returnDate;
      if (typeof parsed.vehicleType === "string") state.vehicleType = parsed.vehicleType;
      if (typeof parsed.selectedCarName === "string") state.selectedCarName = parsed.selectedCarName;
      if (typeof parsed.selectedCarRate === "number" && parsed.selectedCarRate > 0) {
        state.selectedCarRate = parsed.selectedCarRate;
      }
      if (typeof parsed.estDays === "number" && parsed.estDays >= 1) state.estDays = parsed.estDays;
      if (typeof parsed.estDistance === "number" && parsed.estDistance >= 10) {
        state.estDistance = parsed.estDistance;
      }

      return Boolean(
        state.pickupCity ||
          state.pickupDate ||
          state.returnDate ||
          state.selectedCarName ||
          state.vehicleType !== "all"
      );
    } catch {
      return false;
    }
  }

  function setFieldError(inputEl, errorEl, message) {
    if (!inputEl || !errorEl) return;
    if (message) {
      inputEl.setAttribute("aria-invalid", "true");
      errorEl.textContent = message;
      errorEl.hidden = false;
    } else {
      inputEl.removeAttribute("aria-invalid");
      errorEl.textContent = "";
      errorEl.hidden = true;
    }
  }

  function clearAllFieldErrors() {
    setFieldError(pickupCityInput, pickupCityError, "");
    setFieldError(pickupDateInput, pickupDateError, "");
    setFieldError(returnDateInput, returnDateError, "");
  }

  function showSummary(message, isError) {
    if (!searchSummary) return;
    searchSummary.textContent = message;
    searchSummary.hidden = false;
    searchSummary.classList.toggle("is-error", isError);
    searchSummary.classList.toggle("is-success", !isError);
  }

  function hideSummary() {
    if (!searchSummary) return;
    searchSummary.hidden = true;
    searchSummary.textContent = "";
    searchSummary.classList.remove("is-error", "is-success");
  }

  function validateSearchForm() {
    clearAllFieldErrors();
    const today = getTodayISO();
    const city = pickupCityInput.value.trim();
    const start = pickupDateInput.value;
    const end = returnDateInput.value;

    let firstInvalidField = null;

    if (!city) {
      setFieldError(pickupCityInput, pickupCityError, "Please select a pickup city.");
      firstInvalidField = firstInvalidField || pickupCityInput;
    }

    if (!start) {
      setFieldError(pickupDateInput, pickupDateError, "Please choose a pickup date.");
      firstInvalidField = firstInvalidField || pickupDateInput;
    } else if (start < today) {
      setFieldError(pickupDateInput, pickupDateError, "Pickup date cannot be in the past.");
      firstInvalidField = firstInvalidField || pickupDateInput;
    }

    if (!end) {
      setFieldError(returnDateInput, returnDateError, "Please choose a return date.");
      firstInvalidField = firstInvalidField || returnDateInput;
    } else if (start && end <= start) {
      setFieldError(returnDateInput, returnDateError, "Return date must be after the pickup date.");
      firstInvalidField = firstInvalidField || returnDateInput;
    }

    if (firstInvalidField) {
      showSummary("Please fix the highlighted search fields before continuing.", true);
      firstInvalidField.focus();
      return false;
    }

    return true;
  }

  function calculateDaysBetween(startISO, endISO) {
    if (!startISO || !endISO) return null;
    const diffMs = new Date(endISO) - new Date(startISO);
    const days = Math.round(diffMs / (1000 * 60 * 60 * 24));
    return days > 0 ? days : null;
  }

  function updateHubChips() {
    hubButtons.forEach((btn) => {
      const isMatch = btn.dataset.hub === state.pickupCity;
      btn.classList.toggle("is-active", isMatch);
      btn.setAttribute("aria-pressed", String(isMatch));
    });
  }

  function updateAccountBanner() {
    if (!accountStatusText) return;
    const parts = [];
    if (state.pickupCity) parts.push(`Hub: ${state.pickupCity}`);
    if (state.pickupDate && state.returnDate) {
      parts.push(`Dates: ${state.pickupDate} to ${state.returnDate}`);
    }
    if (state.selectedCarName) parts.push(`Vehicle: ${state.selectedCarName}`);

    accountStatusText.textContent =
      parts.length > 0
        ? `Saved trip preferences — ${parts.join(" | ")}.`
        : "Your latest pickup city, dates, and selected vehicle are saved locally in this browser for quick checkout.";
  }

  function applyVehicleFilter(category, cityFilter) {
    const normalizedCategory = category || "all";
    const normalizedCity = (cityFilter || "").trim();

    let visibleCount = 0;

    vehicleCards.forEach((card) => {
      const cardCat = card.dataset.category || "";
      const cardCities = (card.dataset.city || "").split(",").map((c) => c.trim());
      const matchesCat = normalizedCategory === "all" || cardCat === normalizedCategory;
      const matchesCity = !normalizedCity || cardCities.includes(normalizedCity);

      const isVisible = matchesCat && matchesCity;
      card.hidden = !isVisible;
      if (isVisible) visibleCount += 1;
    });

    filterButtons.forEach((btn) => {
      const isActive = btn.dataset.category === normalizedCategory;
      btn.classList.toggle("is-active", isActive);
      btn.setAttribute("aria-pressed", String(isActive));
    });

    if (vehicleTypeSelect && vehicleTypeSelect.value !== normalizedCategory) {
      vehicleTypeSelect.value = normalizedCategory;
    }

    if (fleetFilterStatus) {
      const cityLabel = normalizedCity ? ` in ${normalizedCity}` : "";
      const catLabel = normalizedCategory === "all" ? "all categories" : `${normalizedCategory} category`;
      fleetFilterStatus.textContent =
        visibleCount > 0
          ? `Showing ${visibleCount} vehicle${visibleCount === 1 ? "" : "s"} for ${catLabel}${cityLabel}.`
          : `No vehicles match ${catLabel}${cityLabel}. Try selecting "All" or another pickup hub.`;
    }
  }

  function applySelectedVehicle(carName, rate) {
    state.selectedCarName = carName || "";
    if (rate) state.selectedCarRate = Number(rate) || state.selectedCarRate;

    vehicleCards.forEach((card) => {
      const btn = card.querySelector(".btn-select-car");
      const matches = Boolean(carName && btn && btn.dataset.carName === carName);
      card.classList.toggle("is-selected", matches);
    });

    if (selectedVehicleNotice) {
      if (state.selectedCarName) {
        selectedVehicleNotice.hidden = false;
        selectedVehicleNotice.textContent = `Selected vehicle: ${state.selectedCarName} ($${state.selectedCarRate}/day). Ready to confirm in Booking or estimate fuel below.`;
      } else {
        selectedVehicleNotice.hidden = true;
        selectedVehicleNotice.textContent = "";
      }
    }

    updateEstimator();
    updateAccountBanner();
    saveState();
  }

  function updateEstimator() {
    if (!estDaysInput || !estDistanceInput || !estimatorResult) return;

    const days = Math.max(1, Math.min(60, Number(estDaysInput.value) || 1));
    const distance = Math.max(10, Math.min(5000, Number(estDistanceInput.value) || 10));

    state.estDays = days;
    state.estDistance = distance;

    const dailyRate = state.selectedCarRate || 54;
    const rentalSubtotal = days * dailyRate;
    const fuelOrChargeEstimate = Math.round(distance * 0.085);
    const total = rentalSubtotal + fuelOrChargeEstimate;

    estimatorResult.innerHTML = `Estimated Total: <strong>$${total}</strong> ($${rentalSubtotal} rental + $${fuelOrChargeEstimate} est. fuel/energy)`;
    saveState();
  }

  // Mobile Menu Navigation
  if (navToggle && primaryNav) {
    navToggle.addEventListener("click", () => {
      const isExpanded = navToggle.getAttribute("aria-expanded") === "true";
      navToggle.setAttribute("aria-expanded", String(!isExpanded));
      primaryNav.classList.toggle("is-open", !isExpanded);
    });

    primaryNav.querySelectorAll("a").forEach((link) => {
      link.addEventListener("click", () => {
        navToggle.setAttribute("aria-expanded", "false");
        primaryNav.classList.remove("is-open");
      });
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && primaryNav.classList.contains("is-open")) {
        navToggle.setAttribute("aria-expanded", "false");
        primaryNav.classList.remove("is-open");
        navToggle.focus();
      }
    });
  }

  // Search Form Events
  if (searchForm) {
    const today = getTodayISO();
    pickupDateInput.min = today;
    returnDateInput.min = today;

    pickupCityInput.addEventListener("change", () => {
      state.pickupCity = pickupCityInput.value;
      setFieldError(pickupCityInput, pickupCityError, "");
      updateHubChips();
      applyVehicleFilter(state.vehicleType, state.pickupCity);
      updateAccountBanner();
      saveState();
    });

    pickupDateInput.addEventListener("change", () => {
      state.pickupDate = pickupDateInput.value;
      setFieldError(pickupDateInput, pickupDateError, "");
      if (pickupDateInput.value) {
        returnDateInput.min = pickupDateInput.value;
      }
      saveState();
    });

    returnDateInput.addEventListener("change", () => {
      state.returnDate = returnDateInput.value;
      setFieldError(returnDateInput, returnDateError, "");
      saveState();
    });

    vehicleTypeSelect.addEventListener("change", () => {
      state.vehicleType = vehicleTypeSelect.value;
      applyVehicleFilter(state.vehicleType, state.pickupCity);
      saveState();
    });

    searchForm.addEventListener("submit", (event) => {
      event.preventDefault();
      if (!validateSearchForm()) return;

      state.pickupCity = pickupCityInput.value;
      state.pickupDate = pickupDateInput.value;
      state.returnDate = returnDateInput.value;
      state.vehicleType = vehicleTypeSelect.value;

      const tripDays = calculateDaysBetween(state.pickupDate, state.returnDate);
      if (tripDays && estDaysInput) {
        estDaysInput.value = String(tripDays);
        updateEstimator();
      }

      applyVehicleFilter(state.vehicleType, state.pickupCity);
      updateHubChips();
      updateAccountBanner();
      saveState();

      if (savedStateBadge) savedStateBadge.hidden = false;

      const dayText = tripDays ? ` for ${tripDays} day${tripDays === 1 ? "" : "s"}` : "";
      showSummary(
        `Search saved: ${state.pickupCity} (${state.pickupDate} to ${state.returnDate}${dayText}). Fleet updated below.`,
        false
      );
    });
  }

  if (resetSearchBtn) {
    resetSearchBtn.addEventListener("click", () => {
      state.pickupCity = "";
      state.pickupDate = "";
      state.returnDate = "";
      state.vehicleType = "all";
      state.selectedCarName = "";
      state.selectedCarRate = 54;

      if (searchForm) searchForm.reset();
      clearAllFieldErrors();
      hideSummary();
      if (savedStateBadge) savedStateBadge.hidden = true;

      try {
        localStorage.removeItem(STORAGE_KEY);
      } catch {
        // Ignore storage errors.
      }

      updateHubChips();
      applySelectedVehicle("", 54);
      applyVehicleFilter("all", "");
      updateAccountBanner();
    });
  }

  // Fleet Category Filter Buttons
  filterButtons.forEach((btn) => {
    btn.addEventListener("click", () => {
      state.vehicleType = btn.dataset.category || "all";
      applyVehicleFilter(state.vehicleType, state.pickupCity);
      saveState();
    });
  });

  // Select Vehicle Buttons
  selectCarButtons.forEach((btn) => {
    btn.addEventListener("click", () => {
      const carName = btn.dataset.carName || "";
      const rate = Number(btn.dataset.rate) || 54;
      applySelectedVehicle(carName, rate);
    });
  });

  // Pickup Hub Quick-Select Chips
  hubButtons.forEach((btn) => {
    btn.addEventListener("click", () => {
      const city = btn.dataset.hub || "";
      state.pickupCity = city;
      if (pickupCityInput) {
        pickupCityInput.value = city;
        setFieldError(pickupCityInput, pickupCityError, "");
      }
      updateHubChips();
      applyVehicleFilter(state.vehicleType, state.pickupCity);
      updateAccountBanner();
      saveState();
    });
  });

  prefillCityLinks.forEach((link) => {
    link.addEventListener("click", () => {
      const city = link.dataset.prefillCity || "";
      if (!city) return;
      state.pickupCity = city;
      if (pickupCityInput) {
        pickupCityInput.value = city;
        setFieldError(pickupCityInput, pickupCityError, "");
      }
      updateHubChips();
      applyVehicleFilter(state.vehicleType, state.pickupCity);
      updateAccountBanner();
      saveState();
    });
  });

  // Fare & Fuel Estimator Inputs
  if (estDaysInput && estDistanceInput) {
    estDaysInput.addEventListener("input", updateEstimator);
    estDistanceInput.addEventListener("input", updateEstimator);
  }

  // Initialize from Saved localStorage State
  function init() {
    const hasSaved = loadState();

    if (pickupCityInput) pickupCityInput.value = state.pickupCity;
    if (pickupDateInput) pickupDateInput.value = state.pickupDate;
    if (returnDateInput) returnDateInput.value = state.returnDate;
    if (vehicleTypeSelect) vehicleTypeSelect.value = state.vehicleType;
    if (estDaysInput) estDaysInput.value = String(state.estDays);
    if (estDistanceInput) estDistanceInput.value = String(state.estDistance);

    if (savedStateBadge) savedStateBadge.hidden = !hasSaved;

    updateHubChips();
    applySelectedVehicle(state.selectedCarName, state.selectedCarRate);
    applyVehicleFilter(state.vehicleType, state.pickupCity);
    updateEstimator();
    updateAccountBanner();
  }

  init();
})();

